let notificationRefreshVersion=0;
function appendNotificationItems(root,items){for(const item of items){const section=document.createElement('section');card(section,[item.title,item.body,item.readAt?'Leída':'Sin leer']);if(!item.readAt){const button=document.createElement('button');button.textContent='Marcar como leída';button.onclick=async()=>{button.disabled=true;try{await api('/me/notifications/'+encodeURIComponent(item.id)+'/read',send('POST',{version:item.version},key()));await refreshNotifications()}catch(error){byId('notifications-status').textContent=error.message;button.disabled=false}};section.append(button)}root.append(section)}}
async function refreshNotifications(){const refreshVersion=++notificationRefreshVersion,preferences=byId('notification-preferences'),inbox=byId('notification-inbox'),status=byId('notifications-status');status.textContent='Cargando notificaciones…';preferences.replaceChildren();inbox.replaceChildren();const results=await Promise.allSettled([api('/me/notification-preferences'),api('/me/notifications')]);if(refreshVersion!==notificationRefreshVersion)return;status.textContent='';if(results[0].status==='fulfilled'){const data=results[0].value;card(preferences,['El envío por correo, SMS y WhatsApp todavía no está disponible.']);for(const [category,label] of [['TRANSACTIONAL','Avisos de tu cuenta y servicios'],['SUPPORT','Avisos de soporte']]){const preference=data.items.find(item=>item.category===category&&item.channel==='IN_APP')||{enabled:true,version:0};const section=document.createElement('section');card(section,[label,preference.enabled?'Activados':'Desactivados']);const button=document.createElement('button');button.textContent=(preference.enabled?'Desactivar ':'Activar ')+label.toLowerCase();button.onclick=async()=>{button.disabled=true;try{await api('/me/notification-preferences',send('POST',{category,channel:'IN_APP',enabled:!preference.enabled,contactMethodId:null,version:preference.version},key()));await refreshNotifications()}catch(error){status.textContent=error.message;button.disabled=false}};section.append(button);preferences.append(section)}}else{card(preferences,['No fue posible consultar tus preferencias. Puedes volver a actualizar esta sección.']);status.textContent=results[0].reason?.message||'Preferencias no disponibles.'}if(results[1].status==='fulfilled'){const data=results[1].value;if(!data.items.length)card(inbox,['No tienes notificaciones.']);const items=document.createElement('div'),pagination=document.createElement('div');appendNotificationItems(items,data.items);inbox.append(items,pagination);let cursor=data.nextCursor,loading=false;const renderPagination=()=>{pagination.replaceChildren();if(!cursor)return;const button=document.createElement('button');button.textContent='Cargar notificaciones anteriores';button.onclick=async()=>{if(loading||refreshVersion!==notificationRefreshVersion)return;loading=true;button.disabled=true;status.textContent='Cargando notificaciones anteriores…';try{const page=await api('/me/notifications?cursor='+encodeURIComponent(cursor));if(refreshVersion!==notificationRefreshVersion)return;appendNotificationItems(items,page.items);cursor=page.nextCursor;renderPagination();status.textContent='Notificaciones anteriores cargadas.'}catch(error){if(refreshVersion===notificationRefreshVersion){status.textContent=error.message;button.disabled=false}}finally{loading=false}};pagination.append(button)};renderPagination()}else{card(inbox,['No fue posible consultar tu bandeja. Puedes volver a actualizar esta sección.']);status.textContent=results[1].reason?.message||'Bandeja no disponible.'}}
